/// Full 64-point graph retained as the scalar/reference implementation.
#[inline(always)]
pub(crate) fn fdct64<V: super::forward_lanes::ForwardLanes>(
    input: &[V; 64],
    output: &mut [V; 64],
    cospi: &[i32; 64],
    cos_bit: u32,
) {
    fdct64_impl::<V, false>(input, output, cospi, cos_bit);
}

/// Exact low32 outputs; entries32..63 are scratch and must not be consumed.
#[inline(always)]
pub(crate) fn fdct64_low32<V: super::forward_lanes::ForwardLanes>(
    input: &[V; 64],
    output: &mut [V; 64],
    cospi: &[i32; 64],
    cos_bit: u32,
) {
    fdct64_impl::<V, true>(input, output, cospi, cos_bit);
}

